  rejectCompact("-0430");
  rejectCompact("-0445");
  rejectCompact("-0300");
  rejectCompact("-0330");
  rejectCompact("-0345");
  rejectCompact("-0200");
  rejectCompact("-0230");
  rejectCompact("-0245");
  rejectCompact("-0100");
  rejectCompact("-0130");
  rejectCompact("-0145");
  rejectCompact("+0000");
  rejectCompact("+0030");
  rejectCompact("+0045");
  rejectCompact("+0100");
  rejectCompact("+0130");
  rejectCompact("+0145");
  rejectCompact("+0200");
  rejectCompact("+0230");
  rejectCompact("+0245");
  rejectCompact("+0300");
  rejectCompact("+0330");
  rejectCompact("+0345");
  rejectCompact("+0400");
  rejectCompact("+0430");
  rejectCompact("+0445");
  rejectCompact("+0500");
  rejectCompact("+0530");
  rejectCompact("+0545");
  rejectCompact("+0600");
  rejectCompact("+0630");
  rejectCompact("+0645");
  rejectCompact("+0700");
  rejectCompact("+0730");
  rejectCompact("+0745");
  if (compact && !record.has(match[2] + (match[3] || "00"))) throw new TypeError("colon");
  return {hours, minutes, compact};
}

